-- Esquema criado pelo Hibernate (ddl-auto=update) até 17/11/2026, tal como está nas bases de dados existentes.
-- Usado pelo MigracoesTest para simular a primeira passagem pelo Liquibase.
create table audit_evento (data_hora timestamp(6) not null, entidade_id bigint, id bigint generated by default as identity, jogo_id bigint, entidade_tipo varchar(30), acao varchar(40) not null check ((acao in ('ALTERACAO_PREMIO','GERACAO_LINK_PASSWORD','DESBLOQUEIO_UTILIZADOR','CANCELAMENTO_INSCRICAO','CRIACAO_PREMIO','INSCRICAO_JOGO','ALTERACAO_ROLE','FALTA_COMPARENCIA','REABERTURA_FASE','PUBLICACAO_EQUIPAS','LOGIN','VOTO','ALTERACAO_PASSWORD','CANCELAMENTO_JOGO','CRIACAO_JOGO','FECHO_JOGO','REDEFINICAO_PASSWORD','ANULACAO_GOLO','ANULACAO_VOTO','PROMOCAO_LISTA_ESPERA','ALTERACAO_VOTO','CRIACAO_CONVITE','MUDANCA_EQUIPA','ADICAO_CONVIDADO','REGISTO_GOLO','REGISTO_UTILIZADOR','FECHO_CONVOCATORIA','DEFINICAO_RESULTADO','REATIVACAO_JOGO','ALTERACAO_DADOS','GERACAO_EQUIPAS','FECHO_VOTACAO','BLOQUEIO_UTILIZADOR'))), ator varchar(40), detalhes varchar(500), primary key (id));
create table golo (assistencia_id bigint, id bigint generated by default as identity, jogo_id bigint not null, marcador_id bigint, registado_em timestamp(6) not null, registado_por_id bigint, equipa varchar(20) not null check ((equipa in ('COLETES','SEM_COLETES'))), primary key (id));
create table inscricao (faltou boolean default false not null, cancelado_em timestamp(6), cancelado_por_id bigint, id bigint generated by default as identity, inscrito_em timestamp(6) not null, jogador_id bigint, jogo_id bigint not null, equipa varchar(20) check ((equipa in ('COLETES','SEM_COLETES'))), estado varchar(20) not null check ((estado in ('CANCELADA','ATIVA'))), nome_convidado varchar(60), primary key (id));
create table jogo (vagas integer not null, cancelado_em timestamp(6), cancelado_por_id bigint, criado_em timestamp(6) not null, criado_por_id bigint not null, data_hora timestamp(6) not null, id bigint generated by default as identity, estado varchar(30) not null check ((estado in ('VOTACAO_ABERTA','CONVOCATORIA_ABERTA','CANCELADO','EQUIPAS_PUBLICADAS','EM_REGISTO','CONVOCATORIA_FECHADA','FECHADO'))), estado_antes_cancelamento varchar(30) check ((estado_antes_cancelamento in ('VOTACAO_ABERTA','CONVOCATORIA_ABERTA','CANCELADO','EQUIPAS_PUBLICADAS','EM_REGISTO','CONVOCATORIA_FECHADA','FECHADO'))), local_jogo varchar(120) not null, motivo_cancelamento varchar(200), primary key (id));
create table premio (ativo boolean not null, ordem integer not null, criado_em timestamp(6) not null, id bigint generated by default as identity, nome varchar(40) not null unique, descricao varchar(120), primary key (id));
create table utilizador (bloqueado boolean default false not null, defesa integer, passe integer, remate integer, tecnica integer, velocidade integer, bloqueado_em timestamp(6), criado_em timestamp(6) not null, id bigint generated by default as identity, pe varchar(10) check ((pe in ('DIREITO','ESQUERDO','AMBOS'))), posicao varchar(20) check ((posicao in ('AVANCADO','GUARDA_REDES','DEFESA','MEDIO'))), posicao_secundaria varchar(20) check ((posicao_secundaria in ('AVANCADO','GUARDA_REDES','DEFESA','MEDIO'))), alcunha varchar(30), username varchar(40) not null unique, nome varchar(60) not null, password_hash varchar(255) not null, primary key (id));
create table utilizador_role (utilizador_id bigint not null, role varchar(20) not null check ((role in ('ORGANIZADOR','JOGADOR','ADMIN'))), primary key (utilizador_id, role));
create table voto (anulado boolean default false not null, anulado_por_id bigint, criado_em timestamp(6) not null, eleitor_id bigint not null, id bigint generated by default as identity, jogo_id bigint not null, premio_id bigint, votado_id bigint not null, primary key (id));
create index idx_audit_data_hora on audit_evento (data_hora);
create index idx_audit_jogo on audit_evento (jogo_id);
create index idx_audit_ator on audit_evento (ator);
